//! Bedrock model family detection and capability routing.

/// Identifies the model family of a Bedrock Converse model ID.
///
/// Used internally to select capability flags, schema rewriter rulesets, and
/// tool-choice support. The `#[non_exhaustive]` attribute allows future
/// additions without a breaking change.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ModelFamily {
    /// Anthropic Claude model family (e.g. `anthropic.claude-*`).
    Anthropic,
    /// Amazon Nova model family (e.g. `amazon.nova-*`).
    AmazonNova,
    /// Amazon Titan model family (e.g. `amazon.titan-*`).
    AmazonTitan,
    /// Meta Llama model family (e.g. `meta.llama*`).
    Llama,
    /// Mistral model family (e.g. `mistral.mistral-*`).
    Mistral,
    /// Cohere Command model family (e.g. `cohere.command-*`).
    Cohere,
    /// Unknown or unrecognized model family.
    Unknown,
}

impl ModelFamily {
    /// Detect the model family from a Bedrock model ID.
    ///
    /// When the first segment is not a known provider name, detection reads
    /// the second segment. So a geographic prefix such as `us.`, `eu.`,
    /// `apac.`, `jp.`, `au.`, `ca.`, `in.` or `global.` is skipped, and a
    /// future prefix is skipped too. An ARN is classified by its resource ID
    /// (the text after the last `/`). Opaque IDs, such as application
    /// inference profile ARNs, give [`ModelFamily::Unknown`].
    ///
    /// # Examples
    ///
    /// ```
    /// use paigasus_helikon_providers_bedrock::ModelFamily;
    /// assert_eq!(
    ///     ModelFamily::from_model_id("anthropic.claude-3-5-sonnet-20241022-v2:0"),
    ///     ModelFamily::Anthropic,
    /// );
    /// assert_eq!(
    ///     ModelFamily::from_model_id("global.anthropic.claude-sonnet-5-5"),
    ///     ModelFamily::Anthropic,
    /// );
    /// ```
    pub fn from_model_id(model_id: &str) -> Self {
        let lowered = model_id.to_ascii_lowercase();
        let mut id = lowered.as_str();
        if id.starts_with("arn:") {
            match id.rsplit_once('/') {
                Some((_, resource)) => id = resource,
                None => return Self::Unknown,
            }
        }

        let (first, rest1) = id.split_once('.').unwrap_or((id, ""));
        let (second, rest2) = rest1.split_once('.').unwrap_or((rest1, ""));

        Self::classify(first, rest1)
            .or_else(|| Self::classify(second, rest2))
            .unwrap_or(if first.contains("llama") || second.contains("llama") {
                Self::Llama
            } else {
                Self::Unknown
            })
    }

    /// Map a provider segment (and the text after it) to a family, or `None`
    /// when the segment is not a known provider name.
    fn classify(provider: &str, rest: &str) -> Option<Self> {
        match provider {
            "anthropic" => Some(Self::Anthropic),
            "amazon" => Some(if rest.starts_with("nova") {
                Self::AmazonNova
            } else if rest.starts_with("titan") {
                Self::AmazonTitan
            } else {
                Self::Unknown
            }),
            "meta" => Some(Self::Llama),
            "mistral" => Some(Self::Mistral),
            "cohere" => Some(Self::Cohere),
            _ => None,
        }
    }

    /// Returns `true` when the family supports Bedrock's forced-tool-choice
    /// (`toolChoice: { tool: { name } }`) request field.
    ///
    /// Families that do not support it will have the `tool_choice` field
    /// omitted and a `debug!` log emitted instead.
    pub(crate) fn supports_forced_tool_choice(self) -> bool {
        matches!(self, Self::Anthropic | Self::Mistral | Self::AmazonNova)
    }
}

#[cfg(test)]
mod tests {
    use super::ModelFamily::*;
    use super::*;

    #[test]
    fn detects_families_from_bedrock_model_ids() {
        for (id, want) in [
            ("anthropic.claude-3-5-sonnet-20241022-v2:0", Anthropic),
            ("us.anthropic.claude-3-7-sonnet-20250219-v1:0", Anthropic), // cross-region inference profile prefix
            ("apac.anthropic.claude-3-5-sonnet-20241022-v2:0", Anthropic), // apac prefix
            ("amazon.nova-pro-v1:0", AmazonNova),
            ("amazon.titan-text-express-v1", AmazonTitan),
            ("meta.llama3-1-70b-instruct-v1:0", Llama),
            ("mistral.mistral-large-2407-v1:0", Mistral),
            ("cohere.command-r-plus-v1:0", Cohere),
            ("some.future-model", Unknown),
        ] {
            assert_eq!(ModelFamily::from_model_id(id), want, "id={id}");
        }
    }

    #[test]
    fn detects_family_behind_any_leading_segment() {
        for (id, want) in [
            ("us.anthropic.claude-sonnet-4-5-20250929-v1:0", Anthropic),
            ("eu.anthropic.claude-haiku-4-5-20251001-v1:0", Anthropic),
            ("apac.amazon.nova-pro-v1:0", AmazonNova),
            ("jp.anthropic.claude-sonnet-4-5-20250929-v1:0", Anthropic),
            ("au.anthropic.claude-sonnet-5-5", Anthropic),
            ("ca.anthropic.claude-sonnet-5-5", Anthropic),
            ("in.anthropic.claude-haiku-4-5-20251001-v1:0", Anthropic),
            ("global.anthropic.claude-sonnet-4-5-20250929-v1:0", Anthropic),
            ("global.anthropic.claude-sonnet-5-5", Anthropic),
            ("ap.anthropic.claude-x", Anthropic),
            ("us-gov.anthropic.claude-3-5-sonnet-20240620-v1:0", Anthropic),
            ("global.amazon.nova-2-lite-v1:0", AmazonNova),
            ("us.meta.llama3-2-90b-instruct-v1:0", Llama),
            ("eu.mistral.pixtral-large-2502-v1:0", Mistral),
            ("zz.anthropic.claude-x", Anthropic),
            ("us.deepseek.r1-v1:0", Unknown),
            ("us.writer.palmyra-x5-v1:0", Unknown),
            ("amazon.anthropic.x", Unknown),
            ("us.llama3-x", Llama),
            ("GLOBAL.Anthropic.claude-x", Anthropic),
            ("US.anthropic.x", Anthropic),
            ("", Unknown),
            (".", Unknown),
            ("..anthropic.x", Unknown),
            ("global.", Unknown),
            ("global.anthropic", Anthropic),
            ("arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-3-5-sonnet-20241022-v2:0", Anthropic),
            ("ARN:aws:bedrock:us-east-1::foundation-model/anthropic.claude-x", Anthropic),
            ("arn:aws:bedrock:us-east-1:123456789012:inference-profile/us.anthropic.claude-3-5-sonnet-20241022-v2:0", Anthropic),
            ("arn:aws:bedrock:us-east-1:123456789012:default-prompt-router/anthropic.claude:1", Anthropic),
            ("arn:aws:bedrock:us-east-1:123456789012:application-inference-profile/a1b2c3d4e5f6", Unknown),
            ("arn:aws:bedrock:us-east-1:123456789012:inference-profile/", Unknown),
            ("arn:aws:bedrock", Unknown),
        ] {
            assert_eq!(ModelFamily::from_model_id(id), want, "id={id}");
        }
    }

    #[test]
    fn forced_tool_choice_support() {
        assert!(Anthropic.supports_forced_tool_choice());
        assert!(Mistral.supports_forced_tool_choice());
        assert!(AmazonNova.supports_forced_tool_choice());
        assert!(!Llama.supports_forced_tool_choice());
        assert!(!AmazonTitan.supports_forced_tool_choice());
    }
}
//! Model capability flags for Bedrock model families.
//!
//! Returns conservative defaults for unknown families; callers may override
//! via [`crate::BedrockModelBuilder::capabilities`].

use crate::family::ModelFamily;
use paigasus_helikon_core::ModelCapabilities;

/// Return the capability flags for a family.
///
/// The `structured_output` flag is set for families that support forced
/// tool-choice (the mechanism used to synthesize structured output on Bedrock).
/// No per-family `max_output_tokens` default is returned; omitting
/// `inferenceConfig.maxTokens` lets the model apply its own correct default,
/// which avoids `ValidationException` on models whose limit is below any
/// hardcoded value.  Callers may supply an explicit default via
/// [`crate::BedrockModelBuilder::max_output_tokens_default`].
pub(crate) fn caps_for(family: ModelFamily) -> ModelCapabilities {
    match family {
        ModelFamily::Anthropic => ModelCapabilities::empty()
            .with_streaming()
            .with_tools()
            .with_parallel_tool_calls()
            .with_structured_output(),
        ModelFamily::AmazonNova => ModelCapabilities::empty()
            .with_streaming()
            .with_tools()
            .with_parallel_tool_calls()
            .with_structured_output(),
        ModelFamily::AmazonTitan => ModelCapabilities::empty().with_streaming().with_tools(),
        ModelFamily::Llama => ModelCapabilities::empty().with_streaming().with_tools(),
        ModelFamily::Mistral => ModelCapabilities::empty()
            .with_streaming()
            .with_tools()
            .with_parallel_tool_calls()
            .with_structured_output(),
        ModelFamily::Cohere => ModelCapabilities::empty().with_streaming().with_tools(),
        ModelFamily::Unknown => ModelCapabilities::empty().with_streaming().with_tools(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::family::ModelFamily;

    #[test]
    fn anthropic_has_full_capabilities() {
        let caps = caps_for(ModelFamily::Anthropic);
        assert!(caps.streaming, "anthropic: streaming");
        assert!(caps.tools, "anthropic: tools");
        assert!(caps.parallel_tool_calls, "anthropic: parallel");
        assert!(caps.structured_output, "anthropic: structured_output");
        assert!(
            !caps.vision,
            "anthropic: vision not advertised (no image-block mapping)"
        );
    }

    #[test]
    fn llama_has_streaming_and_tools_but_not_structured_output() {
        let caps = caps_for(ModelFamily::Llama);
        assert!(caps.streaming, "llama: streaming");
        assert!(caps.tools, "llama: tools");
        assert!(!caps.structured_output, "llama: no structured_output");
    }

    #[test]
    fn unknown_has_conservative_defaults() {
        let caps = caps_for(ModelFamily::Unknown);
        assert!(caps.streaming, "unknown: streaming");
        assert!(caps.tools, "unknown: tools");
        assert!(!caps.structured_output, "unknown: no structured_output");
        assert!(!caps.vision, "unknown: no vision");
    }

    #[test]
    fn amazon_nova_supports_structured_output() {
        let caps = caps_for(ModelFamily::AmazonNova);
        assert!(caps.structured_output, "nova: structured_output");
        assert!(caps.parallel_tool_calls, "nova: parallel");
        assert!(
            !caps.vision,
            "nova: vision not advertised (no image-block mapping)"
        );
    }

    #[test]
    fn amazon_titan_does_not_support_structured_output() {
        let caps = caps_for(ModelFamily::AmazonTitan);
        assert!(caps.streaming);
        assert!(caps.tools);
        assert!(!caps.structured_output);
    }

    #[test]
    fn mistral_supports_parallel_tool_calls() {
        let caps = caps_for(ModelFamily::Mistral);
        assert!(caps.parallel_tool_calls, "mistral: parallel_tool_calls");
        assert!(caps.structured_output, "mistral: structured_output");
    }

    #[test]
    fn structured_output_matches_forced_tool_choice_support() {
        // structured_output flag should align with supports_forced_tool_choice
        for family in [
            ModelFamily::Anthropic,
            ModelFamily::AmazonNova,
            ModelFamily::AmazonTitan,
            ModelFamily::Llama,
            ModelFamily::Mistral,
            ModelFamily::Cohere,
            ModelFamily::Unknown,
        ] {
            let caps = caps_for(family);
            assert_eq!(
                caps.structured_output,
                family.supports_forced_tool_choice(),
                "family {family:?}: structured_output != supports_forced_tool_choice"
            );
        }
    }
}
//! `ResponseFormat` → synthesized forced-tool + tool_choice for Bedrock Converse.
//!
//! When the model family supports forced tool choice, `JsonSchema` / `JsonObject`
//! response formats are synthesized into a hidden tool named [`SYNTHESIZED_TOOL_NAME`]
//! with a matching `toolChoice: {tool: {name}}` that forces the model to call it.
//! Families that do NOT support forced tool choice (e.g. Llama, Titan) return
//! `synthesizing: false`; the caller degrades to plain text.

use aws_sdk_bedrockruntime::types::{
    SpecificToolChoice, ToolChoice as BedrockToolChoice, ToolInputSchema, ToolSpecification,
};
use paigasus_helikon_core::{ModelError, ResponseFormat};

use crate::document::value_to_document;
use crate::family::ModelFamily;
use crate::translate::schema::{rewrite_tool_schema, Ruleset};
use crate::translate::tools::SYNTHESIZED_TOOL_NAME;

/// Outcome of [`synthesize`].
pub(crate) struct Synthesized {
    /// Synthesized tool to append to the tool list (if any).
    pub(crate) tool: Option<ToolSpecification>,
    /// `toolChoice` to include in `ToolConfiguration` (if any).
    pub(crate) tool_choice: Option<BedrockToolChoice>,
    /// `true` when the stream translator should remap the synthesized tool's
    /// output to a `TokenDelta`.
    pub(crate) synthesizing: bool,
}

/// Build the synthesized tool + `toolChoice` for the given response format.
///
/// Returns `synthesizing: false` for:
/// - `ResponseFormat::Text` / `None` (no synthesis needed),
/// - any format on a family that does not support forced tool choice (degrades
///   to text).
///
/// # Errors
/// Currently infallible (reserved-name and conflict guards are in `mod.rs`
/// where `tool_choice` is also available).
pub(crate) fn synthesize(
    rf: Option<&ResponseFormat>,
    family: ModelFamily,
    ruleset: Ruleset,
) -> Result<Synthesized, ModelError> {
    let no_synthesis = Ok(Synthesized {
        tool: None,
        tool_choice: None,
        synthesizing: false,
    });

    match rf {
        Some(ResponseFormat::JsonSchema { name, schema, .. }) => {
            if !family.supports_forced_tool_choice() {
                tracing::debug!(
                    target: "paigasus::bedrock::translate",
                    family = ?family,
                    "ResponseFormat::JsonSchema not synthesized — family does not support \
                     forced tool choice; degrading to Text",
                );
                return no_synthesis;
            }
            let rewritten = rewrite_tool_schema(schema, ruleset);
            let doc = value_to_document(&rewritten);
            let spec = ToolSpecification::builder()
                .name(SYNTHESIZED_TOOL_NAME)
                .description(format!("Return data matching the {name} schema."))
                .input_schema(ToolInputSchema::Json(doc))
                .build()
                .map_err(|e| {
                    ModelError::Other(anyhow::anyhow!("failed to build synthesized tool: {e}"))
                })?;
            let tc = build_specific_tool_choice(SYNTHESIZED_TOOL_NAME)?;
            Ok(Synthesized {
                tool: Some(spec),
                tool_choice: Some(tc),
                synthesizing: true,
            })
        }

        Some(ResponseFormat::JsonObject) => {
            if !family.supports_forced_tool_choice() {
                tracing::debug!(
                    target: "paigasus::bedrock::translate",
                    family = ?family,
                    "ResponseFormat::JsonObject not synthesized — family does not support \
                     forced tool choice; degrading to Text",
                );
                return no_synthesis;
            }
            let schema = serde_json::json!({"type": "object"});
            let rewritten = rewrite_tool_schema(&schema, ruleset);
            let doc = value_to_document(&rewritten);
            let spec = ToolSpecification::builder()
                .name(SYNTHESIZED_TOOL_NAME)
                .description("Return a JSON object.")
                .input_schema(ToolInputSchema::Json(doc))
                .build()
                .map_err(|e| {
                    ModelError::Other(anyhow::anyhow!("failed to build synthesized tool: {e}"))
                })?;
            let tc = build_specific_tool_choice(SYNTHESIZED_TOOL_NAME)?;
            Ok(Synthesized {
                tool: Some(spec),
                tool_choice: Some(tc),
                synthesizing: true,
            })
        }

        _ => no_synthesis,
    }
}

fn build_specific_tool_choice(name: &str) -> Result<BedrockToolChoice, ModelError> {
    let specific = SpecificToolChoice::builder()
        .name(name)
        .build()
        .map_err(|e| {
            ModelError::Other(anyhow::anyhow!("failed to build SpecificToolChoice: {e}"))
        })?;
    Ok(BedrockToolChoice::Tool(specific))
}

// ── Unit tests ────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use paigasus_helikon_core::ResponseFormat;
    use serde_json::json;

    fn strict_ruleset() -> Ruleset {
        Ruleset::for_family(ModelFamily::Anthropic)
    }

    #[test]
    fn text_format_returns_no_synthesis() {
        let s = synthesize(
            Some(&ResponseFormat::Text),
            ModelFamily::Anthropic,
            strict_ruleset(),
        )
        .unwrap();
        assert!(!s.synthesizing);
        assert!(s.tool.is_none());
        assert!(s.tool_choice.is_none());
    }

    #[test]
    fn none_format_returns_no_synthesis() {
        let s = synthesize(None, ModelFamily::Anthropic, strict_ruleset()).unwrap();
        assert!(!s.synthesizing);
    }

    #[test]
    fn json_schema_on_anthropic_synthesizes_tool_and_tool_choice() {
        let rf = ResponseFormat::JsonSchema {
            name: "Person".to_owned(),
            schema: json!({"type": "object", "properties": {"name": {"type": "string"}}}),
            strict: false,
        };
        let s = synthesize(Some(&rf), ModelFamily::Anthropic, strict_ruleset()).unwrap();
        assert!(s.synthesizing);
        let tool = s.tool.unwrap();
        assert_eq!(tool.name(), SYNTHESIZED_TOOL_NAME);
        assert!(tool.description().unwrap().contains("Person"));
        assert!(tool.input_schema().unwrap().is_json());
        // tool_choice should be Tool variant
        let tc = s.tool_choice.unwrap();
        assert!(tc.is_tool());
        assert_eq!(tc.as_tool().unwrap().name(), SYNTHESIZED_TOOL_NAME);
    }

    #[test]
    fn json_schema_on_llama_returns_no_synthesis() {
        let rf = ResponseFormat::JsonSchema {
            name: "X".to_owned(),
            schema: json!({"type": "object"}),
            strict: false,
        };
        let s = synthesize(Some(&rf), ModelFamily::Llama, strict_ruleset()).unwrap();
        assert!(!s.synthesizing);
        assert!(s.tool.is_none());
        assert!(s.tool_choice.is_none());
    }

    #[test]
    fn json_schema_on_titan_returns_no_synthesis() {
        let rf = ResponseFormat::JsonSchema {
            name: "X".to_owned(),
            schema: json!({"type": "object"}),
            strict: false,
        };
        let s = synthesize(Some(&rf), ModelFamily::AmazonTitan, strict_ruleset()).unwrap();
        assert!(!s.synthesizing);
    }

    #[test]
    fn json_object_on_anthropic_synthesizes_with_object_schema() {
        let s = synthesize(
            Some(&ResponseFormat::JsonObject),
            ModelFamily::Anthropic,
            strict_ruleset(),
        )
        .unwrap();
        assert!(s.synthesizing);
        let tool = s.tool.unwrap();
        assert_eq!(tool.name(), SYNTHESIZED_TOOL_NAME);
        assert!(tool.input_schema().is_some());
    }

    #[test]
    fn json_object_on_nova_synthesizes() {
        let s = synthesize(
            Some(&ResponseFormat::JsonObject),
            ModelFamily::AmazonNova,
            strict_ruleset(),
        )
        .unwrap();
        assert!(s.synthesizing);
    }

    #[test]
    fn json_object_on_llama_returns_no_synthesis() {
        let s = synthesize(
            Some(&ResponseFormat::JsonObject),
            ModelFamily::Llama,
            strict_ruleset(),
        )
        .unwrap();
        assert!(!s.synthesizing);
    }
}
//! `ToolDef` → Bedrock `ToolSpecification` translation.
//!
//! Each `ToolDef.schema` is run through `rewrite_tool_schema` before being
//! converted to a Smithy `Document` via `value_to_document`.

use aws_sdk_bedrockruntime::types::{ToolInputSchema, ToolSpecification};
use paigasus_helikon_core::{ModelError, ToolDef};

use crate::document::value_to_document;
use crate::translate::schema::{rewrite_tool_schema, Ruleset};

/// Reserved tool name used internally for structured-output synthesis.
///
/// User-provided tools with this name are rejected to avoid collisions.
pub const SYNTHESIZED_TOOL_NAME: &str = "__paigasus_structured_output__";

/// Translate a slice of [`ToolDef`]s into Bedrock [`ToolSpecification`]s.
///
/// # Errors
/// Returns [`ModelError::Other`] when any tool name equals
/// [`SYNTHESIZED_TOOL_NAME`] (reserved for structured-output synthesis).
pub(crate) fn tool_specs(
    defs: &[ToolDef],
    ruleset: Ruleset,
) -> Result<Vec<ToolSpecification>, ModelError> {
    let mut specs = Vec::with_capacity(defs.len());
    for def in defs {
        if def.name == SYNTHESIZED_TOOL_NAME {
            return Err(ModelError::Other(anyhow::anyhow!(
                "tool name '{SYNTHESIZED_TOOL_NAME}' is reserved by the Bedrock provider \
                 for structured-output synthesis",
            )));
        }
        let rewritten = rewrite_tool_schema(&def.schema, ruleset);
        let doc = value_to_document(&rewritten);
        let spec = ToolSpecification::builder()
            .name(&def.name)
            .description(&def.description)
            .input_schema(ToolInputSchema::Json(doc))
            .build()
            .map_err(|e| {
                ModelError::Other(anyhow::anyhow!("failed to build ToolSpecification: {e}"))
            })?;
        specs.push(spec);
    }
    Ok(specs)
}

// ── Unit tests ────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn simple_def(name: &str) -> ToolDef {
        ToolDef {
            name: name.to_owned(),
            description: "a tool".to_owned(),
            schema: json!({"type": "object", "properties": {"x": {"type": "string"}}}),
        }
    }

    #[test]
    fn empty_defs_returns_empty_vec() {
        let specs = tool_specs(&[], Ruleset::Strict).unwrap();
        assert!(specs.is_empty());
    }

    #[test]
    fn translates_name_and_description() {
        let defs = vec![simple_def("search")];
        let specs = tool_specs(&defs, Ruleset::Strict).unwrap();
        assert_eq!(specs.len(), 1);
        assert_eq!(specs[0].name(), "search");
        assert_eq!(specs[0].description(), Some("a tool"));
    }

    #[test]
    fn schema_becomes_json_input_schema() {
        let defs = vec![simple_def("ping")];
        let specs = tool_specs(&defs, Ruleset::Strict).unwrap();
        assert!(specs[0].input_schema().is_some());
        assert!(specs[0].input_schema().unwrap().is_json());
    }

    #[test]
    fn reserved_name_returns_error() {
        let defs = vec![ToolDef {
            name: SYNTHESIZED_TOOL_NAME.to_owned(),
            description: "bad".to_owned(),
            schema: json!({}),
        }];
        let err = tool_specs(&defs, Ruleset::Strict).unwrap_err();
        assert!(matches!(err, ModelError::Other(_)));
        let msg = format!("{err}");
        assert!(msg.contains("reserved"));
    }

    #[test]
    fn schema_rewriter_strips_unsupported_keywords() {
        // $schema should be stripped by the Strict rewriter.
        let defs = vec![ToolDef {
            name: "foo".to_owned(),
            description: "".to_owned(),
            schema: json!({
                "$schema": "http://json-schema.org/draft-07/schema#",
                "type": "object",
                "properties": {"n": {"type": "integer"}}
            }),
        }];
        let specs = tool_specs(&defs, Ruleset::Strict).unwrap();
        // The Document should not contain "$schema" — we can only verify this
        // indirectly by confirming the spec was built successfully (the rewriter
        // is unit-tested in schema.rs).
        assert_eq!(specs.len(), 1);
    }
}

